Below is a self‑contained **C++ program** that demonstrates the most common ways to use templates:

```cpp
#include <iostream>
#include <string>
#include <type_traits>

/* --------------------------------------------------------------
   1.  Function template : a generic max() function
   -------------------------------------------------------------- */
template <typename T>
T myMax(const T& a, const T& b)
{
    return (a > b) ? a : b;          // works for any type that defines operator>
}

/* --------------------------------------------------------------
   2.  Class template : a simple pair container
   -------------------------------------------------------------- */
template <typename T1, typename T2>
class MyPair
{
public:
    T1 first;
    T2 second;

    MyPair(const T1& f = T1(), const T2& s = T2())
        : first(f), second(s) {}

    void print() const
    {
        std::cout << "(" << first << ", " << second << ")\n";
    }
};

/* --------------------------------------------------------------
   3.  Partial specialization : MyPair for a pointer as the first
      template argument – we add a helper to print the pointed‑to
      value instead of the raw pointer address.
   -------------------------------------------------------------- */
template <typename T2>
class MyPair<T2*, T2>
{
public:
    T2* first;      // pointer
    T2 second;      // same type as the pointee

    MyPair(T2* f = nullptr, const T2& s = T2())
        : first(f), second(s) {}

    void print() const
    {
        std::cout << "("
                  << (first ? *first : 0) << ", "
                  << second << ")\n";
    }
};

/* --------------------------------------------------------------
   4.  Template argument deduction with SFINAE
      Only enable myAdd() for arithmetic types
   -------------------------------------------------------------- */
template <typename T,
          std::enable_if_t<std::is_arithmetic_v<T>, int> = 0>
T myAdd(const T& a, const T& b)
{
    return a + b;
}

/* --------------------------------------------------------------
   Main program : use the templates above
   -------------------------------------------------------------- */
int main()
{
    // 1. Function template
    std::cout << "max(3, 7) = " << myMax(3, 7) << '\n';
    std::cout << "max(\"abc\", \"xyz\") = "
              << myMax(std::string("abc"), std::string("xyz")) << '\n';

    // 2. Generic class template
    MyPair<int, double> p1(10, 3.14);
    p1.print();                  // (10, 3.14)

    // 3. Partially specialized class template
    int val = 42;
    MyPair<int*, int> p2(&val, 100);
    p2.print();                  // (42, 100)

    // 4. SFINAE enabled function template
    std::cout << "add(5, 10) = " << myAdd(5, 10) << '\n';
    // std::cout << "add(\"a\", \"b\") = " << myAdd("a", "b") << '\n'; // <-- compile‑error

    return 0;
}
```

### What this code shows

| Feature | How it’s illustrated |
|---------|----------------------|
| **Function template** | `myMax<T>` – works for any type that supports `operator>` |
| **Class template** | `MyPair<T1,T2>` – a generic container that can hold two different types |
| **Partial specialization** | `MyPair<T2*,T2>` – changes the printing logic when the first element is a pointer |
| **SFINAE / `enable_if`** | `myAdd<T>` – only compiles for arithmetic types, giving a compile‑time safety net |

Compile with a modern compiler (e.g., `g++ -std=c++20 main.cpp`) and you’ll see output similar to:

```
max(3, 7) = 7
max("abc", "xyz") = abc
(10, 3.14)
(42, 100)
add(5, 10) = 15
```

Feel free to adapt or expand on this skeleton to suit your needs!
